            ip_routes=[
                {
                    "cidr_ip": "10.0.0.0/24",
                    "description": "On-premises network",
                },
                {
                    "cidr_ip": "192.168.100.0/24",
                    "description": "Peered VPC",
                },
            ],
            directory_id=example.id,
